sys_module.content:
(function process(request, response) {
    response.setContentType('application/json');
    const writer = response.getStreamWriter();

    function safeJsonParse(s) {
        try { return JSON.parse(s); } catch (e) { return null; }
    }

    function getParam(name) {
        try {
            if (request && request.queryParams) {
                if (request.queryParams[name] !== undefined && request.queryParams[name] !== null && request.queryParams[name] !== '') {
                    return '' + request.queryParams[name];
                }
            }
            if (request && typeof request.getParameter === 'function') {
                const v2 = request.getParameter(name);
                if (v2 !== null && v2 !== undefined && v2 !== '') return '' + v2;
            }
        } catch (e) { }
        return null;
    }

    try {
        const connectionService = new x_1955226_peeklo_1.SalesforceConnectionService();
        const lookup = connectionService.getCurrentUserConnection();
        if (!lookup || !lookup.success) {
            response.setStatus(401);
            writer.writeString(JSON.stringify({
                success: false,
                error: (lookup && lookup.error) ? lookup.error : 'No active connection found'
            }));
            return;
        }

        const details = connectionService.getConnectionDetails(lookup.connection_id);
        if (!details || !details.success || !details.connection) {
            response.setStatus(401);
            writer.writeString(JSON.stringify({
                success: false,
                error: (details && details.error) ? details.error : 'Connection details not found'
            }));
            return;
        }

        const connection = details.connection;
        if (!connection.instance_url) {
            response.setStatus(400);
            writer.writeString(JSON.stringify({
                success: false,
                error: 'Salesforce instance_url is missing on the connection'
            }));
            return;
        }

        const oauthService = new x_1955226_peeklo_1.SalesforceOAuthService();
        const accessToken = oauthService.ensureValidAccessToken({
            connection: connection,
            connectionService: connectionService
        });
        if (!accessToken) {
            response.setStatus(401);
            writer.writeString(JSON.stringify({
                success: false,
                error: 'Unable to obtain Salesforce access token (re-authorize the connection)'
            }));
            return;
        }

        const objectName = getParam('object_name') || getParam('objectName');
        if (!objectName) {
            response.setStatus(400);
            writer.writeString(JSON.stringify({
                success: false,
                error: 'Missing required parameter: object_name'
            }));
            return;
        }


        const recordId = getParam('record_id') || getParam('recordId');


        var selectedRelationshipNames = new Set();
        try {
            var objConfigGr = new GlideRecord('x_1955226_peeklo_1_salesforce_object_config');
            objConfigGr.addQuery('sf_object_name', objectName);
            objConfigGr.query();

            if (objConfigGr.next()) {
                var objectConfigSysId = objConfigGr.getUniqueValue();


                var selectedRelGr = new GlideRecord('x_1955226_peeklo_1_salesforce_selected_related_objects');
                selectedRelGr.addQuery('object_config', objectConfigSysId);
                selectedRelGr.addQuery('active', true);
                selectedRelGr.query();

                while (selectedRelGr.next()) {
                    var relName = selectedRelGr.getValue('relationship_name');
                    if (relName) {
                        selectedRelationshipNames.add(relName);
                    }
                }
            }
        } catch (dbErr) {
            gs.warn('Error fetching selected related objects: ' + dbErr.message);
        }

        const instanceUrl = connection.instance_url.replace(/\/+$/, '');

        const describeEndpoint = instanceUrl + '/services/data/v58.0/sobjects/' + objectName + '/describe';
        const describeReq = new sn_ws.RESTMessageV2();
        describeReq.setEndpoint(describeEndpoint);
        describeReq.setHttpMethod('GET');
        describeReq.setRequestHeader('Authorization', 'Bearer ' + accessToken);
        describeReq.setRequestHeader('Accept', 'application/json');

        const describeRes = describeReq.execute();
        const describeStatus = describeRes.getStatusCode();
        const describeBody = describeRes.getBody();
        const describeData = safeJsonParse(describeBody);

        if (describeStatus < 200 || describeStatus >= 300 || !describeData) {
            response.setStatus(describeStatus || 500);
            writer.writeString(JSON.stringify({
                success: false,
                error: 'Failed to get object describe: ' + (describeData && describeData.message ? describeData.message : describeBody || 'Unknown error')
            }));
            return;
        }


        let childRelationships = describeData.childRelationships || [];



        const relatedObjects = [];
        const seenNames = {}; 

        for (var i = 0; i < childRelationships.length; i++) {
            var rel = childRelationships[i];


            if (!rel.relationshipName || !rel.childSObject || !rel.field) {
                continue;
            }

            var relationshipName = rel.relationshipName;


            if (!seenNames[relationshipName]) {
                relatedObjects.push({
                    name: rel.label || rel.relationshipName,
                    relationshipName: relationshipName,
                    selected: selectedRelationshipNames.has(relationshipName)
                });
                seenNames[relationshipName] = true;
            }
        }


        relatedObjects.sort(function(a, b) {
            return a.name.localeCompare(b.name);
        });

        response.setStatus(200);
        writer.writeString(JSON.stringify({
            success: true,
            objectName: objectName,
            recordId: recordId || null,
            relatedObjects: relatedObjects,
            totalCount: relatedObjects.length
        }));

    } catch (error) {
        gs.error('Error in Salesforce related object GET handler: ' + error.message + '\nStack: ' + error.stack);
        response.setStatus(500);
        writer.writeString(JSON.stringify({
            success: false,
            error: 'Internal server error: ' + error.message
        }));
    }

})(request, response);
